// Validation du payload — échoue tôt et explicitement plutôt que de produire
// un document silencieusement incomplet (cf. azy.daily#139 : PDF « réussi » sans hébreu).
const body = $input.first().json.body || $input.first().json;
const err = (msg) => { throw new Error(msg); };

const data = body.data || body;
if (!data || typeof data !== 'object') err('payload invalide : objet "data" attendu');
if (!data.massekhet) err('champ requis manquant : data.massekhet');
if (!data.daf) err('champ requis manquant : data.daf');
if (!Array.isArray(data.paragraphes) || data.paragraphes.length === 0) {
  err('champ requis manquant ou vide : data.paragraphes (tableau non vide)');
}

let nbComm = 0, nbHeb = 0;
data.paragraphes.forEach((p, i) => {
  if (typeof p.num !== 'number') err(`paragraphes[${i}].num doit être un nombre`);
  if (typeof p.hebreu !== 'string') err(`paragraphes[${i}].hebreu doit être une chaîne`);
  if (typeof p.traduction !== 'string') err(`paragraphes[${i}].traduction doit être une chaîne`);
  const cs = p.commentaires || [];
  if (!Array.isArray(cs)) err(`paragraphes[${i}].commentaires doit être un tableau`);
  cs.forEach((c, j) => {
    if (!c.auteur) err(`paragraphes[${i}].commentaires[${j}].auteur manquant`);
    if (typeof c.hebreu !== 'string') err(`paragraphes[${i}].commentaires[${j}].hebreu doit être une chaîne`);
    if (typeof c.traduction !== 'string') err(`paragraphes[${i}].commentaires[${j}].traduction doit être une chaîne`);
  });
  nbComm += cs.length;
  nbHeb += (p.hebreu.match(/[֐-׿]/g) || []).length;
  cs.forEach(c => { nbHeb += (c.hebreu.match(/[֐-׿]/g) || []).length; });
});

if (nbHeb === 0) err('aucun caractère hébreu dans les données — refus de générer un document vide');

return [{ json: {
  data,
  filename: body.filename || `${data.massekhet}_${data.daf}.pdf`,
  correlation_id: body.correlation_id || null,
  stats_entree: { paragraphes: data.paragraphes.length, commentaires: nbComm, caracteres_hebreu: nbHeb },
} }];

// Assets statiques du template « bavli-visavis », embarqués pour que le
// workflow soit auto-suffisant (aucune dépendance réseau à un serveur de fichiers).
//   - styles.css : le design (RTL, polices, grille vis-à-vis)
//   - EBGaramond : sous-ensemble latin (84 Ko au lieu de 831 Ko)
//   - logo       : WebP détouré, 400 px de haut (46 Ko au lieu de 1310 Ko)
// Régénérer via docs/samples/gen_workflow.py après toute modification du design.
const CSS = "/* Template « vis-à-vis » (B v2) — Pesachim et consorts.
   Les marges de page sont pilotées par render.sh (marginTop/Bottom/…),
   PAS ici : le pied de page natif de Gotenberg dessine dans la marge basse,
   et un @page{margin} CSS entrerait en conflit avec lui. */

@page { size: A4; }

:root {
  --encre:  #1C1D22;
  --indigo: #22355C;
  --filet:  #D8DBE2;
  --gris:   #6C7280;
}

/* EB Garamond embarquée dans le bundle (fichier envoyé à Gotenberg).
   Repli : Liberation Serif, présente dans l'image gotenberg:8. */
@font-face {
  font-family: "EB Garamond";
  src: url("EBGaramond.ttf");
  font-weight: 400 700;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  color: var(--encre);
  font-family: "EB Garamond", "Liberation Serif", Georgia, serif;
}

/* ---------- première page : logo + en-tête de daf ---------- */

.logo-bloc { text-align: center; margin-bottom: .5cm; }
.logo      { height: 2.6cm; max-width: 60%; object-fit: contain; }

.tete {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: baseline;
  direction: rtl;
  border-bottom: double 3px var(--indigo);
  padding-bottom: .25cm;
}
.tete .perek {
  font-family: "Noto Sans Hebrew", sans-serif;
  font-size: 9pt;
  color: var(--gris);
  text-align: right;
}
.tete .massekhet {
  font-family: "Noto Serif Hebrew", serif;
  font-size: 21pt;
  font-weight: 700;
  color: var(--indigo);
}
.tete .folio {
  font-family: "Noto Serif Hebrew", serif;
  font-size: 15pt;
  font-weight: 700;
  color: var(--indigo);
  text-align: left;
}
.sous-tete {
  text-align: center;
  font-size: 8pt;
  letter-spacing: .3em;
  text-transform: uppercase;
  color: var(--gris);
  margin: .3cm 0 .9cm;
}

/* ---------- paragraphe : vis-à-vis principal ---------- */

.par { margin-bottom: 1.1cm; }

.visavis {
  display: grid;
  grid-template-columns: 1fr 1cm 1.06fr;
  align-items: start;
  /* garder guemara + début de traduction ensemble en bas de page */
  break-inside: avoid;
}

.heb-principal {
  direction: rtl;
  unicode-bidi: isolate;
  text-align: right;               /* jamais justify sur le vocalisé */
  margin: 0;
  font-family: "Noto Serif Hebrew", serif;
  font-size: 12.5pt;
  line-height: 1.95;               /* air pour les nekudot */
  font-weight: 600;
}

.fr-principal {
  direction: ltr;
  unicode-bidi: isolate;
  text-align: left;
  margin: 0;
  font-size: 11pt;
  line-height: 1.62;
}

.pivot {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .15cm;
  align-self: stretch;
}
.medaillon {
  width: .65cm;
  height: .65cm;
  border: 1px solid var(--indigo);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8pt;
  color: var(--indigo);
  font-weight: 600;
  flex: none;
}
.fil { flex: 1; width: 1px; background: var(--filet); }

/* ---------- apparat des commentaires ---------- */

.apparat {
  margin-top: .5cm;
  border-top: 1px solid var(--encre);
}

.commentaire {
  padding: .3cm 0;
  border-bottom: 1px dotted var(--filet);
  break-inside: avoid;             /* Chromium coupera quand même les très longs */
}
.commentaire:last-child { border-bottom: none; }

.auteur {
  font-variant: small-caps;
  letter-spacing: .1em;
  font-size: 10pt;
  color: var(--indigo);
  font-weight: 600;
  margin-bottom: .1cm;
  break-after: avoid;              /* pas de nom orphelin en bas de page */
}
.auteur .ord { font-variant: normal; font-size: 8pt; color: var(--gris); }

.duo {
  display: grid;
  grid-template-columns: 1fr 1cm 1.06fr;
}
.duo .heb {
  grid-column: 1;
  direction: rtl;
  unicode-bidi: isolate;
  text-align: right;
  margin: 0;
  font-family: "Noto Serif Hebrew", serif;
  font-size: 9pt;
  line-height: 1.8;
  color: #2A2C33;
}
.commentaire.rashi .duo .heb {
  font-family: "Noto Rashi Hebrew", "Noto Serif Hebrew", serif;
  font-size: 9.5pt;
  line-height: 1.72;
}
.duo .fr {
  grid-column: 3;
  direction: ltr;
  unicode-bidi: isolate;
  margin: 0;
  font-size: 8.5pt;
  line-height: 1.55;
  color: #4A4E58;
}
";
const FONT_B64 = '';
const LOGO_B64 = '';

return [{ json: { ...$input.first().json, assets: { css: CSS, font: FONT_B64, logo: LOGO_B64 } } }];

// Portage JS de docs/samples/build.py (template « vis-à-vis »).
// Produit index.html ET footer.html EN MÉMOIRE : le sandbox du Code node n'a pas
// d'accès disque, contrairement au script Python d'origine qui écrivait footer.html.
const src = $input.first().json;
const d = src.data;

const MASSEKHTOT = {
  "Berakhot":"ברכות","Shabbat":"שבת","Eruvin":"עירובין","Pesachim":"פסחים","Yoma":"יומא",
  "Sukkah":"סוכה","Beitzah":"ביצה","Rosh Hashanah":"ראש השנה","Taanit":"תענית","Megillah":"מגילה",
  "Moed Katan":"מועד קטן","Chagigah":"חגיגה","Yevamot":"יבמות","Ketubot":"כתובות","Nedarim":"נדרים",
  "Nazir":"נזיר","Sotah":"סוטה","Gittin":"גיטין","Kiddushin":"קידושין","Bava Kamma":"בבא קמא",
  "Bava Metzia":"בבא מציעא","Bava Batra":"בבא בתרא","Sanhedrin":"סנהדרין","Makkot":"מכות",
  "Shevuot":"שבועות","Avodah Zarah":"עבודה זרה","Horayot":"הוריות","Zevachim":"זבחים",
  "Menachot":"מנחות","Chullin":"חולין","Bekhorot":"בכורות","Arakhin":"ערכין","Temurah":"תמורה",
  "Keritot":"כריתות","Meilah":"מעילה","Niddah":"נדה"
};
const GRAPHIE_RASHI = new Set(['Rashi', 'Tosafot']);

const UNITES   = ['','א','ב','ג','ד','ה','ו','ז','ח','ט'];
const DIZAINES = ['','י','כ','ל','מ','נ','ס','ע','פ','צ'];
const CENTAINES= ['','ק','ר','ש','ת'];

function gematria(n) {
  const r = n % 100;
  if (r === 15) return CENTAINES[Math.floor(n/100)] + 'טו';
  if (r === 16) return CENTAINES[Math.floor(n/100)] + 'טז';
  return CENTAINES[Math.floor(n/100)] + DIZAINES[Math.floor(r/10)] + UNITES[n % 10];
}
function dafHebreu(daf) {
  const s = String(daf).trim().toLowerCase();
  const m = s.match(/^(\d+)([ab])$/);
  if (!m) return daf;
  return `דף ${gematria(parseInt(m[1],10))} ${m[2] === 'a' ? 'ע״א' : 'ע״ב'}`;
}
// échappement obligatoire : un « < » ou « & » dans le texte casserait le document
function e(s) {
  return String(s == null ? '' : s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

function rendreParagraphe(p) {
  const cs = p.commentaires || [];
  // auteurs répétés : numérotés, JAMAIS dédupliqués ni regroupés (l'ordre fait foi)
  const total = {};
  cs.forEach(c => { total[c.auteur] = (total[c.auteur] || 0) + 1; });
  const vus = {};
  const blocs = cs.map(c => {
    const a = c.auteur;
    vus[a] = (vus[a] || 0) + 1;
    let label = e(a);
    if (total[a] > 1) label += ` <span class="ord">· ${vus[a]}</span>`;
    const cls = GRAPHIE_RASHI.has(a) ? ' rashi' : '';
    return `<div class="commentaire${cls}">
<div class="auteur">${label}</div>
<div class="duo">
<p class="heb">${e(c.hebreu)}</p>
<p class="fr">${e(c.traduction)}</p>
</div></div>`;
  }).join('');
  return `<section class="par">
<div class="visavis">
<p class="heb-principal">${e(p.hebreu)}</p>
<div class="pivot"><span class="medaillon">${p.num}</span><span class="fil"></span></div>
<p class="fr-principal">${e(p.traduction)}</p>
</div>
<div class="apparat">${blocs}</div>
</section>`;
}

const titre = `${d.massekhet} ${d.daf}`;
const corps = d.paragraphes.map(rendreParagraphe).join('');

// CSS et assets injectés en ligne : un seul fichier HTML, aucun chemin relatif à gérer
const a = src.assets;
const cssInline = a.css
  .replace('url("EBGaramond.ttf")', `url(data:font/ttf;base64,${a.font})`);

const indexHtml = `<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<title>${e(titre)}</title>
<style>${cssInline}</style>
</head>
<body>
<div class="logo-bloc"><img class="logo" src="data:image/webp;base64,${a.logo}" alt=""></div>
<div class="tete">
  <div class="perek">תלמוד בבלי</div>
  <div class="massekhet">מסכת ${MASSEKHTOT[d.massekhet] || e(d.massekhet)}</div>
  <div class="folio">${dafHebreu(d.daf)}</div>
</div>
<div class="sous-tete">${e(titre)} · Édition bilingue</div>
${corps}
</body>
</html>`;

const footerHtml = `<html>
<head>
<style>
  body { margin:0; padding:0 68px; width:100%; box-sizing:border-box;
         font-family:'Noto Sans Hebrew','DejaVu Sans',sans-serif;
         font-size:8px; color:#6C7280; }
  .pied { display:flex; justify-content:space-between; align-items:baseline;
          width:100%; border-top:1px solid #D8DBE2; padding-top:4px;
          letter-spacing:.12em; text-transform:uppercase; }
  .num { font-weight:600; color:#22355C; }
</style>
</head>
<body>
  <div class="pied">
    <span>${e(titre)}</span>
    <span class="num"><span class="pageNumber"></span> / <span class="totalPages"></span></span>
  </div>
</body>
</html>`;

return [{ json: {
  filename: src.filename,
  correlation_id: src.correlation_id,
  stats_entree: src.stats_entree,
  index_html: indexHtml,
  footer_html: footerHtml,
} }];

// Appel Gotenberg en multipart/form-data.
// Le corps est construit À LA MAIN en Buffer : c'est indépendant du support de
// « formData » par le sandbox, et Buffer est disponible (cf. Claude - Batch Poller).
const src = $input.first().json;
const base = $env.GOTENBERG_URL;
if (!base) throw new Error('GOTENBERG_URL non défini dans l\'environnement n8n');

const B = '----n8nGotenberg' + Date.now().toString(16);
const parts = [];

function champFichier(nom, contenu, type) {
  parts.push(Buffer.from(
    `--${B}\r\nContent-Disposition: form-data; name="files"; filename="${nom}"\r\n` +
    `Content-Type: ${type}\r\n\r\n`, 'utf8'));
  parts.push(Buffer.from(contenu, 'utf8'));
  parts.push(Buffer.from('\r\n', 'utf8'));
}
function champTexte(nom, valeur) {
  parts.push(Buffer.from(
    `--${B}\r\nContent-Disposition: form-data; name="${nom}"\r\n\r\n${valeur}\r\n`, 'utf8'));
}

// index.html : nom OBLIGATOIRE, c'est le point d'entrée de Gotenberg
champFichier('index.html', src.index_html, 'text/html');
champFichier('footer.html', src.footer_html, 'text/html');

// A4 en pouces ; les marges sont pilotées ici et NON en CSS (@page{margin} entrerait
// en conflit avec le pied de page natif, qui dessine dans la marge basse)
champTexte('paperWidth', '8.27');
champTexte('paperHeight', '11.7');
champTexte('marginTop', '0.7');
champTexte('marginBottom', '0.7');
champTexte('marginLeft', '0.7');
champTexte('marginRight', '0.7');
champTexte('printBackground', 'true');
// pas de champ « footerHtml » : Gotenberg utilise AUTOMATIQUEMENT un fichier
// envoyé sous le nom footer.html comme pied de page de chaque page.

parts.push(Buffer.from(`--${B}--\r\n`, 'utf8'));
const corps = Buffer.concat(parts);

const reponse = await this.helpers.httpRequest({
  method: 'POST',
  url: `${base}/forms/chromium/convert/html`,
  headers: {
    'Content-Type': `multipart/form-data; boundary=${B}`,
    'Content-Length': String(corps.length),
  },
  body: corps,
  encoding: 'arraybuffer',
  returnFullResponse: true,
  timeout: 120000,
});

const pdf = Buffer.from(reponse.body);
if (pdf.length < 5 || pdf.slice(0, 4).toString('latin1') !== '%PDF') {
  throw new Error(`réponse Gotenberg invalide (${pdf.length} octets, en-tête PDF absent)`);
}

return [{
  json: {
    success: true,
    filename: src.filename,
    correlation_id: src.correlation_id,
    mime_type: 'application/pdf',
    size_bytes: pdf.length,
    stats_entree: src.stats_entree,
  },
  binary: {
    data: await this.helpers.prepareBinaryData(pdf, src.filename, 'application/pdf'),
  },
}];

// Normalise l'erreur pour l'appelant. Contrairement à l'ancien pipeline, un échec
// est TOUJOURS explicite : jamais de « success: true » avec un document vide.
const e = $input.first().json;
return [{ json: {
  success: false,
  error: e.error?.message || e.message || String(e.error || 'erreur inconnue'),
  error_code: 'PDF_GENERATION_FAILED',
} }];
